import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module } from "@nestjs/common";
import { Reflector } from "@nestjs/core";

@Injectable()
export class AuthGuard implements CanActivate {
    constructor(private readonly reflector: Reflector) {}

    canActivate(context: ExecutionContext): boolean {
        return true;
    }
}

@Injectable()
export class ProductsService {
    findAll() {
        return [{ id: "p1", name: "Notebook", price: 4.5 }];
    }
}

@Controller("products")
export class ProductsController {
    private readonly products = new ProductsService();

    @Get()
    list() {
        return this.products.findAll();
    }
}

@Module({ controllers: [ProductsController] })
export class ProductsModule {}
